        if clause_index == n:
            return True
        for value in [0, 1]:
            assignment[clause_index] = value
            if all(any(assignment[i] != 0 for i in clause) for clause in instance):
                if backtrack(assignment, clause_index + 1):
                    return True
            assignment[clause_index] = None
        return False

    assignment = [None] * n
    return backtrack(assignment, 0)

